function placeTop(el){
  var hd=$("header.js-head-main")||$(".js-head-main")||$("header.head-main")||$("header");
  var g=$(".js-product-detail")||$("#single-product")||$(".product-detail")||$(".js-swiper-product")||$(".js-product-form")||$("#product_form");
  if(hd&&getComputedStyle(hd).position!=="fixed"){
    var t=hd; while(t.parentNode&&t.parentNode!==document.body&&t.parentNode.children.length===1) t=t.parentNode;
    t.parentNode.insertBefore(el,t.nextSibling); return;
  }
  if(g){ /* header fijo: el adbar va justo antes del bloque del producto */
    var b=g; while(b.parentNode&&b.parentNode!==document.body&&!/^(MAIN|SECTION)$/.test(b.parentNode.tagName)) b=b.parentNode;
    if(b.closest(".row")) b=b.closest(".row").closest(".container")||b;
    b.parentNode.insertBefore(el,b); return;
  }
  document.body.insertBefore(el,document.body.firstChild);
}
function buildTop(){
  if($("#dz-top")) return;
  css("dz-top-css",
   "#dz-top{font-family:'Poppins',sans-serif;position:relative;z-index:50}"
  +"#dz-topmq{font-family:'Poppins',sans-serif;position:relative;z-index:5;width:100vw;max-width:100vw;left:50%;margin-left:-50vw;clear:both}"
  +"#dz-top .cd{width:100%;padding:8px 0;color:#fff;background:#c47245}"
  +"#dz-top .cw{max-width:1500px;margin:auto;display:flex;justify-content:center;gap:30px;align-items:center;padding:0 15px}"
  +"#dz-top .lt{text-align:center}"
  +"#dz-top .lt h2{margin:0;font-size:24px;line-height:1;color:#fff;font-weight:600;font-family:'Poppins',sans-serif;letter-spacing:1.2px;text-transform:uppercase}"
  +"#dz-top .lt p{font-size:14px;font-weight:300;line-height:1;margin:5px 0 0;opacity:.9;color:#fff}"
  +"#dz-top .rt{display:flex;align-items:center;gap:15px}"
  +"#dz-top .rt div{display:flex;flex-direction:column;align-items:center}"
  +"#dz-top .rt span{font-size:24px;line-height:1;font-weight:800;opacity:.9;letter-spacing:2px;color:#fff}"
  +"#dz-top .rt label{font-size:12px;line-height:1;font-weight:300;color:#fff;margin:0}"
  +"@media(max-width:919px){#dz-top .lt h2{font-size:15px}#dz-top .rt span{font-size:15px}#dz-top .lt p{font-size:10px;margin:2px 0 0}#dz-top .rt label{font-size:8px}}"
  +"#dz-topmq .mq{overflow:hidden;padding:4px;background:#c47245;border-top:1px solid rgba(255,255,255,.18)}"
  +"#dz-topmq .mt{display:flex;gap:50px;white-space:nowrap;animation:dz-mq 16s linear infinite;align-items:center;width:max-content}"
  +"@media(min-width:768px){#dz-topmq .mt{gap:100px}}"
  +"#dz-topmq .mi{display:flex;align-items:center;gap:4px;color:#fff}"
  +"#dz-topmq .mi svg{width:14px;height:14px}"
  +"#dz-topmq .mi span{font-size:13.3px;line-height:20px;font-weight:400}"
  +"@media(max-width:769px){#dz-topmq .mi span{font-size:11.4px}}"
  +"@keyframes dz-mq{from{transform:translateX(0)}to{transform:translateX(-50%)}}");
  var it=[["shield","Garantía de devolución de "+C.garantiaDias+" días"],["card",C.cuotas+" cuotas sin interés"],["gift","Llevá 2, pagá 1"],["tag","Hasta 70% OFF"]];
  var one=it.map(function(x){ return '<div class="mi">'+I[x[0]]+"<span>"+esc(x[1])+"</span></div>"; }).join("");
  var el=document.createElement("div"); el.id="dz-top";
  el.innerHTML='<div class="cd"><div class="cw"><div class="lt"><h2>Rebajas de primavera</h2><p>Comprá hoy y obtené hasta 70% OFF</p></div><div class="rt"><div><span data-h>00</span><label>Hs</label></div><div><span data-m>00</span><label>Min</label></div><div><span data-s>00</span><label>Seg</label></div></div></div></div>'
  ;
  document.body.insertBefore(el,document.body.firstChild);   /* contador: arriba de todo, sobre el header */
  var mq=document.createElement("div"); mq.id="dz-topmq";
  mq.innerHTML='<div class="mq"><div class="mt">'+one+one+one+one+one+"</div></div>";
  placeTop(mq);                                               /* cinta: debajo del header, encima del carrusel */
  function pad(n){ return (n<10?"0":"")+n; }
  function tick(){ var n=new Date(), e=new Date(n.getFullYear(),n.getMonth(),n.getDate()+1), d=Math.max(0,Math.floor((e-n)/1000));
    $("[data-h]",el).textContent=pad(Math.floor(d/3600)); $("[data-m]",el).textContent=pad(Math.floor(d%3600/60)); $("[data-s]",el).textContent=pad(d%60); }
  tick(); setInterval(tick,1000);
}

