  items.forEach(function(it){ var c=$(".js-cart-item-subtotal-compare-price",it), n=$(".js-cart-item-subtotal",it);
    sub+=ars(c&&(c.getAttribute("data-component-value")||c.textContent))||ars(n&&n.textContent)||0; });
  var ft=$("#dz-cf",mc);
