  $("[data-a]",ft).textContent=save2>0?"-"+fmt(save2):"";
  $(".sv",ft).style.display=save2>0?"":"none";
  $("[data-t]",ft).textContent=fmt(total); $("[data-t2]",ft).textContent=fmt(total);
