function montar(){
  if($("#dh")) return;
  var root=document.createElement("div"); root.id="dh";
  root.innerHTML=hero+resenas+razones+semanas+garantia+comp+faq+(H.ocultarPieTema?pie:"");
  var cont=$(".js-home-sections-container")||$("[data-store='home']")||$("main")||$("#main")||$(".js-main-content");
  var head=$("header")||$(".js-head-main");
  if(cont){ Array.prototype.forEach.call(cont.children,function(c){ c.style.display="none"; }); cont.insertBefore(root,cont.firstChild); cont.style.display="block"; }
  else if(head&&head.parentNode){ head.parentNode.insertBefore(root,head.nextSibling); }
  else document.body.insertBefore(root,document.body.firstChild);
  if(H.ocultarPieTema){ $$("footer").forEach(function(f){ if(!root.contains(f)) f.style.display="none"; }); }
  activar(root);
}
function activar(root){
  /* carruseles */
  $$(".car",root).forEach(function(c){
    var t=$(".trk",c), d=$(".dots",c), items=t.children;
    function per(){ var a=items[0]; return a?Math.max(1,Math.round(t.clientWidth/(a.getBoundingClientRect().width+14))):1; }
    function pages(){ return Math.max(1,Math.ceil(items.length-per()+1)); }
    function draw(){ var n=Math.min(pages(),8), cur=Math.round(t.scrollLeft/((t.scrollWidth-t.clientWidth)||1)*(n-1)); d.innerHTML=""; for(var i=0;i<n;i++){ var e=document.createElement("i"); if(i===cur) e.className="on"; (function(k){ e.onclick=function(){ t.scrollTo({left:k/(n-1||1)*(t.scrollWidth-t.clientWidth),behavior:"smooth"}); }; })(i); d.appendChild(e); } }
    t.addEventListener("scroll",function(){ clearTimeout(t._d); t._d=setTimeout(draw,80); },{passive:!0});
    window.addEventListener("resize",draw); draw();
    var step=function(dir){ var a=items[0]; t.scrollBy({left:dir*(a?a.getBoundingClientRect().width+18:300),behavior:"smooth"}); };
    var l=$(".nv.l",c), r=$(".nv.r",c); if(l) l.onclick=function(){ step(-1); }; if(r) r.onclick=function(){ step(1); };
  });
  /* videos */
  root.addEventListener("click",function(e){
    var w=e.target.closest(".vp"); if(!w) return; var v=$("video",w), m=e.target.closest(".vpm"); e.preventDefault();
    if(m){ v.muted=!v.muted; m.innerHTML=v.muted?SPK_OFF:SPK_ON; return; }
    if(v.paused){ $$(".vp video",root).forEach(function(o){ if(o!==v&&!o.paused){ o.pause(); o.closest(".vp").classList.remove("on"); } });
      var p=v.play(); if(p&&p.catch) p.catch(function(){ v.muted=!0; $(".vpm",w).innerHTML=SPK_OFF; v.play(); }); w.classList.add("on"); }
    else { v.pause(); w.classList.remove("on"); }
  });
  /* línea de tiempo progresiva */
  var tl=$(".tl",root); if(tl){ var tf=$(".tf",tl), ws=$$(".tw",tl);
    var fill=function(){ var r=tl.getBoundingClientRect(), vh=window.innerHeight, lim=vh*.65, p=Math.min(1,Math.max(0,(lim-r.top)/r.height));
      tf.style.height=Math.max(0,p*(r.height-28))+"px"; ws.forEach(function(w){ w.classList.toggle("on",w.getBoundingClientRect().top<lim); }); };
    window.addEventListener("scroll",fill,{passive:!0}); window.addEventListener("resize",fill); fill(); }
  /* faq */
  $$(".fi button",root).forEach(function(b){ b.onclick=function(){ var f=b.parentNode, o=f.classList.toggle("op"); b.setAttribute("aria-expanded",o); }; });
  /* newsletter: usa el formulario de la plantilla si existe */
  var nf=$("#dh-nl",root); if(nf) nf.addEventListener("submit",function(e){
    e.preventDefault(); var em=$("#dh-nl-email",root).value.trim(); if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)){ $("#dh-nl-email",root).focus(); return; }
    var tf=$("form[data-store='newsletter-form']")||$$("form").filter(function(f){ return !root.contains(f)&&f.querySelector("input[type=email],input[name=email]"); })[0];
    if(tf){ var inp=tf.querySelector("input[type=email],input[name=email]"); inp.value=em; tf.setAttribute("action",""); var sb=tf.querySelector("[type=submit]"); try{ sb?sb.click():tf.submit(); }catch(x){} }
    nf.innerHTML='<span class="ok">¡Listo! Ya estás en la lista.</span>';
  });
}
